/**
 * next/image loader for static hosting. Images are pre-generated by `npm run images` as
 * /media/<folder>/<name>-<width>.webp; this maps a requested width to the closest variant
 * so next/image can still emit a proper srcset.
 */
const variants: Record<string, number[]> = {
  projects: [720, 1440],
  portrait: [480, 900],
  certifications: [560, 1600],
  gallery: [720, 1440],
};

export default function mediaLoader({ src, width }: { src: string; width: number; quality?: number }): string {
  const match = /^\/media\/([a-z]+)\/([a-z0-9-]+)$/.exec(src);
  if (!match) return src;
  const [, folder = "", name = ""] = match;
  const widths = variants[folder];
  if (!widths) return src;
  const best = widths.find((w) => w >= width) ?? widths[widths.length - 1];
  return `/media/${folder}/${name}-${best}.webp`;
}
